actions.script:
canLogin = false
const name = String(username || '').trim()
let account = ec.entity.find('moqui.security.UserAccount').condition('username', name).disableAuthz().one()
// a JID's localpart is in lower case; the username may not be
if (!account) account = Array.from(ec.entity.find('moqui.security.UserAccount')
        .condition(ec.entity.conditionFactory.makeCondition('username', 'equals', name).ignoreCase())
        .disableAuthz().limit(5).list()).find((row) => String(row.username).toLowerCase() === name.toLowerCase())
if (!account) return
userId = account.userId; username = account.username; displayName = account.userFullName || account.username
const until = account.disabledDateTime ? Number(account.disabledDateTime) : null
canLogin = account.disabled !== 'Y' || (until != null && until < Number(ec.user.nowTimestamp))

tokenList = []
const account = ec.service.sync().name('org.moqui.impl.XmppServices.get#Account').parameter('username', username).call()
if (!account?.userId || !account.canLogin || !userAgentId) return
const rows = ec.entity.find('moqui.xmpp.XmppFastToken').condition('userId', account.userId)
        .condition('userAgentId', String(userAgentId)).condition('expireDate', '>', ec.user.nowTimestamp).disableAuthz().list()
const live = (id) => {
    if (!id) return false
    const password = ec.entity.find('moqui.security.UserAppPassword').condition('appPasswordId', id).disableAuthz().one()
    return !!password && password.userId === account.userId && !password.revokedDate
}
tokenList = Array.from(rows).filter((row) => live(row.appPasswordId))
        .map((row) => ({fastTokenId: row.fastTokenId, token: row.token, appPasswordId: row.appPasswordId}))

const row = ec.entity.find('moqui.xmpp.XmppFastToken').condition('fastTokenId', fastTokenId).forUpdate(true).disableAuthz().one()
if (!row) { ec.message.addError('No such token'); return }
if (!bound) {
    if (count == null || Number(count) <= Number(row.lastCount ?? -1)) { ec.message.addError('A FAST count used before'); return }
    row.lastCount = Number(count)
}
row.lastUsedDate = ec.user.nowTimestamp
row.update()

userList = []
const rows = []
if (userIdList && userIdList.length) rows.push(...Array.from(ec.entity.find('moqui.security.UserAccount')
        .condition('userId', 'in', Array.from(userIdList).slice(0, 200)).selectField('userId').selectField('username').disableAuthz().list()))
for (const name of Array.from(usernameList || []).slice(0, 50)) {
    const account = ec.service.sync().name('org.moqui.impl.XmppServices.get#Account').parameter('username', String(name)).call()
    if (account?.userId) rows.push({userId: account.userId, username: account.username})
}
let allowed = null
if (ec.user.hasPermission('EXTERNAL_USER')) {
    const mine = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('userId', ec.user.userId).condition('leftDate', null)
            .disableAuthz().list()).map((row) => row.chatRoomId)
    allowed = new Set([ec.user.userId])
    if (mine.length) for (const row of ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', 'in', mine).disableAuthz().list())
        if (row.userId) allowed.add(row.userId)
}
userList = rows.filter((row) => row.username && (!allowed || allowed.has(row.userId)))
        .map((row) => ({userId: row.userId, username: row.username}))

const me = ec.user.userId
const rooms = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('userId', me).disableAuthz().list()).map((row) => row.chatRoomId)
const direct = rooms.length ? Array.from(ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', rooms)
        .condition('roomTypeEnumId', 'CrtDirect').disableAuthz().list()).map((row) => row.chatRoomId) : []
const others = new Set()
if (direct.length) for (const row of ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', 'in', direct).disableAuthz().list())
    if (row.userId && row.userId !== me) others.add(row.userId)
userIdList = Array.from(others)

if (userId === ec.user.userId) { ec.message.addError('A direct conversation is with someone else'); return }
const made = ec.service.sync().name('org.moqui.impl.ChatServices.create#Room')
        .parameters({roomTypeEnumId: 'CrtDirect', memberUserIdList: [userId]}).call()
if (ec.message.hasError()) return
chatRoomId = made.chatRoomId

const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.canRead) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
const row = ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', chatRoomId).disableAuthz().one()
let encrypted = false
try { encrypted = row.encrypted === 'Y' || row.encrypted === true } catch (err) { encrypted = false }
room = {chatRoomId: row.chatRoomId, roomTypeEnumId: row.roomTypeEnumId, roomName: row.roomName || access.room?.displayName || '',
    topic: row.topic || '', visibilityEnumId: row.visibilityEnumId, encrypted: encrypted, archived: !!row.archivedDate}
bridged = ec.entity.find('moqui.chat.ChatRoomBridge').condition('chatRoomId', chatRoomId).condition('thruDate', null).disableAuthz().count() > 0
const isDirect = row.roomTypeEnumId === 'CrtDirect'
const members = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).disableAuthz().list())
        .filter((member) => member.userId && (isDirect || !member.leftDate))
const ids = members.map((member) => member.userId)
const names = {}
if (ids.length) for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', ids)
        .selectField('userId').selectField('username').disableAuthz().list()) names[account.userId] = account.username
memberList = members.filter((member) => names[member.userId])
        .map((member) => ({userId: member.userId, username: names[member.userId], roleEnumId: member.roleEnumId || 'CmrMember'}))

const parse = (text) => { if (!text) return {}; try { const value = JSON.parse(text); return value && typeof value === 'object' ? value : {} } catch (err) { return {} } }
eventList = []; complete = true; count = 0
const me = ec.user.userId
let rooms
if (chatRoomId) {
    const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
    if (ec.message.hasError()) return
    if (!access.canRead) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
    rooms = [chatRoomId]
} else {
    const mine = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('userId', me).disableAuthz().list()).map((row) => row.chatRoomId)
    rooms = mine.length ? Array.from(ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', mine)
            .condition('roomTypeEnumId', 'CrtDirect').disableAuthz().list()).map((row) => row.chatRoomId) : []
    if (withUserId && rooms.length) {
        const theirs = new Set(Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', 'in', rooms)
                .condition('userId', withUserId).disableAuthz().list()).map((row) => row.chatRoomId))
        rooms = rooms.filter((room) => theirs.has(room))
    }
}
if (!rooms.length) return
const size = Math.min(Math.max(Number(limit) || 50, 0), 250)
const base = () => {
    let find = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', 'in', rooms).condition('eventTypeEnumId', 'CetMessage')
            .condition('redactedDate', null).disableAuthz()
    if (startDate != null) find = find.condition('sentDate', '>=', new Date(Number(startDate)))
    if (endDate != null) find = find.condition('sentDate', '<=', new Date(Number(endDate)))
    return find
}
count = Number(base().count())
const bound = (seq, roomId) => {
    if (seq == null) return null
    // a bound is an event of the rooms read here, never of another room
    const boundRoom = roomId || chatRoomId
    if (!rooms.includes(boundRoom)) return null
    const row = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', boundRoom).condition('eventSeq', seq).disableAuthz().one()
    return row ? row.sentDate : null
}
let find = base()
if (chatRoomId) {
    if (afterSeq != null) find = find.condition('eventSeq', '>', afterSeq)
    if (beforeSeq != null) find = find.condition('eventSeq', '<', beforeSeq)
} else {
    const after = bound(afterSeq, afterRoomId), before = bound(beforeSeq, beforeRoomId)
    if (after) find = find.condition('sentDate', '>', after)
    if (before) find = find.condition('sentDate', '<', before)
}
const order = chatRoomId ? 'eventSeq' : 'sentDate'
const backwards = latest || (beforeSeq != null && afterSeq == null)
let rows = Array.from(find.orderBy(backwards ? '-' + order : order).limit(size + 1).list())
complete = rows.length <= size
rows = rows.slice(0, size)
if (backwards) rows.reverse()
if (!rows.length) return
const names = {}
const senders = Array.from(new Set(rows.map((row) => row.senderUserId).filter((id) => id)))
if (senders.length) for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', senders)
        .selectField('userId').selectField('username').selectField('userFullName').disableAuthz().list())
    names[account.userId] = account.userFullName || account.username
for (const row of rows) {
    const content = parse(row.contentJson)
    const edit = Array.from(ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', row.chatRoomId).condition('eventTypeEnumId', 'CetEdit')
            .condition('editsEventSeq', row.eventSeq).orderBy('-eventSeq').limit(1).disableAuthz().list())[0]
    const edited = edit ? parse(edit.contentJson) : null
    eventList.push({chatRoomId: row.chatRoomId, eventSeq: Number(row.eventSeq), type: 'message', senderUserId: row.senderUserId ?? null,
        senderName: row.senderUserId ? names[row.senderUserId] || null : null, sentDate: Number(row.sentDate),
        body: edited && edited.body != null ? edited.body : content.body ?? null,
        bodyText: edit ? edit.bodyText ?? null : row.bodyText ?? null,
        attachments: content.attachments || [], replyToEventSeq: row.replyToEventSeq != null ? Number(row.replyToEventSeq) : null,
        clientRef: row.clientRef ?? null, redacted: false,
        content: content.xmppEncrypted ? {xmppEncrypted: content.xmppEncrypted} : {}})
}

const parse = (text) => { if (!text) return {}; try { const value = JSON.parse(text); return value && typeof value === 'object' ? value : {} } catch (err) { return {} } }
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.canRead) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
let find = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).disableAuthz()
if (eventSeq != null) find = find.condition('eventSeq', eventSeq)
else if (clientRef) find = find.condition('clientRef', clientRef).condition('eventTypeEnumId', 'in', ['CetMessage'])
else { ec.message.addError('eventSeq or clientRef is required'); return }
const row = Array.from(find.orderBy('-eventSeq').limit(1).list())[0]
if (!row) { ec.message.addError('No such message'); return }
eventSeq = Number(row.eventSeq); clientRef = row.clientRef ?? null; senderUserId = row.senderUserId ?? null
const reactions = Array.from(ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventTypeEnumId', 'CetReaction')
        .condition('relatesToEventSeq', eventSeq).condition('redactedDate', null).orderBy('eventSeq').disableAuthz().list())
const of = (user) => user ? reactions.filter((reaction) => reaction.senderUserId === user).map((reaction) => parse(reaction.contentJson).key).filter((key) => key) : []
myReactions = of(ec.user.userId); reactorReactions = of(reactorUserId)

const NAMESPACES = ['eu.siacs.conversations.axolotl', 'urn:xmpp:omemo:2']
const me = ec.user.userId
if (!NAMESPACES.includes(namespace)) { ec.message.addError('Not an OMEMO message'); return }
if (String(xml).length > 65536) { ec.message.addError('The encrypted message is too large'); return }
if (clientRef && !/^[A-Za-z0-9_.:-]{1,64}$/.test(clientRef)) clientRef = null
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.canPost) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
const room = ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', chatRoomId).disableAuthz().one()
let encrypted = false
try { encrypted = room.encrypted === 'Y' || room.encrypted === true } catch (err) { encrypted = false }
if (encrypted) { ec.message.addError('This room is end-to-end encrypted in Moqui and is not served over XMPP'); return }
if (ec.entity.find('moqui.chat.ChatRoomBridge').condition('chatRoomId', chatRoomId).condition('thruDate', null).disableAuthz().count() > 0) {
    ec.message.addError('An OMEMO message cannot go to a bridged room'); return
}
if (clientRef) {
    const before = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('senderUserId', me)
            .condition('clientRef', clientRef).disableAuthz().one()
    if (before) { eventSeq = Number(before.eventSeq); return }
}
const notice = ec.l10n.localize('Encrypted message (OMEMO), readable only in the XMPP clients it was sent to')
const appended = ec.service.sync().name('org.moqui.impl.ChatServices.append#Event').parameters({chatRoomId: chatRoomId,
    eventTypeEnumId: 'CetMessage', senderUserId: me, clientRef: clientRef,
    content: {body: '<p><em>' + notice + '</em></p>', unreadable: true, xmppEncrypted: {xml: String(xml), namespace: namespace}}}).disableAuthz().call()
if (ec.message.hasError()) return
eventSeq = appended.eventSeq
ec.service.sync().name('org.moqui.impl.ChatServices.mark#Read').parameters({chatRoomId: chatRoomId, eventSeq: eventSeq}).call()

exists = false; denied = false; itemList = []
const me = ec.user.userId
const owner = ownerUserId || me
const nodeRow = ec.entity.find('moqui.xmpp.XmppPepNode').condition('userId', owner).condition('node', node).disableAuthz().one()
const bookmarks = node === 'urn:xmpp:bookmarks:1' && owner === me
if (!nodeRow && !bookmarks) return
exists = true
accessModel = nodeRow ? nodeRow.accessModel || 'presence' : 'whitelist'
nodeMaxItems = nodeRow && nodeRow.maxItems != null ? String(nodeRow.maxItems) : ''
if (owner !== me) {
    const allowed = ec.service.sync().name('org.moqui.impl.XmppServices.get#PepReaders').parameters({userId: owner, accessModel: accessModel}).call()
    if (!(allowed.userIdList || []).includes(me)) { denied = true; return }
}
let find = ec.entity.find('moqui.xmpp.XmppPepItem').condition('userId', owner).condition('node', node).disableAuthz()
if (itemIdList && itemIdList.length) find = find.condition('itemId', 'in', Array.from(itemIdList))
let rows = Array.from(find.orderBy('-publishedDate').list())
if (maxItems != null && Number(maxItems) >= 0) rows = rows.slice(0, Number(maxItems))
itemList = rows.reverse().map((row) => ({itemId: row.itemId, payloadXml: row.payloadXml}))
if (bookmarks && (!itemIdList || !itemIdList.length)) {
    const kept = new Set(itemList.map((item) => item.itemId))
    const domain = System.getProperty('xmpp_rooms_domain') || ''
    const found = ec.service.sync().name('org.moqui.impl.ChatServices.find#Rooms').parameter('filter', 'rooms').call()
    for (const room of (found.roomList || [])) {
        if (!domain || room.encrypted) continue
        const plain = /^[a-z0-9_.-]+$/.test(room.chatRoomId) && !room.chatRoomId.startsWith('x-')
        const local = plain ? room.chatRoomId : 'x-' + Array.from(String(room.chatRoomId)).map((ch) => ch.charCodeAt(0).toString(16).padStart(2, '0')).join('')
        const jid = local + '@' + domain
        if (kept.has(jid)) continue
        const name = String(room.displayName || room.roomName || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/'/g, '&apos;')
        itemList.push({itemId: jid, payloadXml: `<conference xmlns='urn:xmpp:bookmarks:1' name='${name}' autojoin='true'/>`})
    }
}

open = accessModel === 'open'
const users = new Set([userId])
if (accessModel !== 'whitelist') {
    const rooms = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('userId', userId).condition('leftDate', null)
            .disableAuthz().list()).map((row) => row.chatRoomId)
    if (rooms.length) for (const row of ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', 'in', rooms)
            .condition('leftDate', null).disableAuthz().list()) if (row.userId) users.add(row.userId)
}
userIdList = Array.from(users)
// an open node is any user's to read
if (open && ec.user.userId && !users.has(ec.user.userId) && !ec.user.hasPermission('EXTERNAL_USER')) userIdList.push(ec.user.userId)

preconditionFailed = false; notifyUserIdList = []
const me = ec.user.userId
if (String(node).length > 250 || String(itemId).length > 250) { ec.message.addError('The node or item id is too long'); return }
if (String(payloadXml).length > 262144) { ec.message.addError('The item is too large'); return }
const ACCESS = ['open', 'presence', 'whitelist']
const asked = options || {}
const access = asked.access_model ? String(asked.access_model) : null
if (access && !ACCESS.includes(access)) { preconditionFailed = true; return }
const max = asked.max_items != null && asked.max_items !== '' ? (asked.max_items === 'max' ? 0 : Number(asked.max_items)) : null
// a user's PEP is bounded: so many nodes (an OMEMO bundle is one per device), so many items in each
const MAX_NODES = 200, MAX_ITEMS = 256
let nodeRow = ec.entity.find('moqui.xmpp.XmppPepNode').condition('userId', me).condition('node', node).forUpdate(true).disableAuthz().one()
if (!nodeRow && ec.entity.find('moqui.xmpp.XmppPepNode').condition('userId', me).disableAuthz().count() >= MAX_NODES) {
    ec.message.addError('Too many PEP nodes'); return
}
if (!nodeRow) {
    const omemo = String(node).startsWith('eu.siacs.conversations.axolotl') || String(node).startsWith('urn:xmpp:omemo:2')
    const fallback = node === 'urn:xmpp:bookmarks:1' ? 'whitelist' : omemo ? 'open' : 'presence'
    nodeRow = ec.entity.makeValue('moqui.xmpp.XmppPepNode')
    nodeRow.setFields({userId: me, node: node, accessModel: access || fallback, maxItems: max != null && !Number.isNaN(max) ? max : null,
        createdDate: ec.user.nowTimestamp}, true, null, null)
    nodeRow.create()
} else if ((access && access !== (nodeRow.accessModel || 'presence'))
        || (max != null && !Number.isNaN(max) && nodeRow.maxItems != null && Number(nodeRow.maxItems) !== max)) {
    preconditionFailed = true; return
}
const item = ec.entity.makeValue('moqui.xmpp.XmppPepItem')
item.setFields({userId: me, node: node, itemId: itemId, payloadXml: String(payloadXml), publishedDate: ec.user.nowTimestamp}, true, null, null)
item.createOrUpdate()
const keep = nodeRow.maxItems != null && Number(nodeRow.maxItems) > 0 ? Math.min(Number(nodeRow.maxItems), MAX_ITEMS) : MAX_ITEMS
if (ec.entity.find('moqui.xmpp.XmppPepItem').condition('userId', me).condition('node', node).disableAuthz().count() > keep) {
    const extra = Array.from(ec.entity.find('moqui.xmpp.XmppPepItem').condition('userId', me).condition('node', node)
            .orderBy('-publishedDate').disableAuthz().list()).slice(keep)
    for (const old of extra) old.delete()
}
notifyUserIdList = ec.service.sync().name('org.moqui.impl.XmppServices.get#PepReaders')
        .parameters({userId: me, accessModel: nodeRow.accessModel || 'presence'}).call().userIdList || []

const me = ec.user.userId
const nodeRow = ec.entity.find('moqui.xmpp.XmppPepNode').condition('userId', me).condition('node', node).disableAuthz().one()
if (!nodeRow) { ec.message.addError('No such node'); return }
ec.entity.find('moqui.xmpp.XmppPepItem').condition('userId', me).condition('node', node).condition('itemId', itemId).disableAuthz().deleteAll()
notifyUserIdList = ec.service.sync().name('org.moqui.impl.XmppServices.get#PepReaders')
        .parameters({userId: me, accessModel: nodeRow.accessModel || 'presence'}).call().userIdList || []

const nodeRow = ec.entity.find('moqui.xmpp.XmppPepNode').condition('userId', ec.user.userId).condition('node', node).disableAuthz().one()
if (!nodeRow) { ec.message.addError('No such node'); return }
const asked = options || {}
if (asked.access_model) {
    if (!['open', 'presence', 'whitelist'].includes(String(asked.access_model))) { ec.message.addError('Unknown access model'); return }
    nodeRow.accessModel = String(asked.access_model)
}
if (asked.max_items != null && asked.max_items !== '') nodeRow.maxItems = asked.max_items === 'max' ? 0 : Number(asked.max_items)
nodeRow.update()

const me = ec.user.userId
ec.entity.find('moqui.xmpp.XmppPepItem').condition('userId', me).condition('node', node).disableAuthz().deleteAll()
const removed = ec.entity.find('moqui.xmpp.XmppPepNode').condition('userId', me).condition('node', node).disableAuthz().deleteAll()
if (!removed) ec.message.addError('No such node')

for (const jid of Array.from(jidList).slice(0, 500)) {
    const text = String(jid).trim().toLowerCase()
    if (!text || text.length > 250) continue
    const row = ec.entity.makeValue('moqui.xmpp.XmppBlockedJid')
    row.setFields({userId: ec.user.userId, jid: text, createdDate: ec.user.nowTimestamp}, true, null, null)
    row.createOrUpdate()
}

let find = ec.entity.find('moqui.xmpp.XmppBlockedJid').condition('userId', ec.user.userId).disableAuthz()
if (jidList && jidList.length) find = find.condition('jid', 'in', Array.from(jidList).map((jid) => String(jid).trim().toLowerCase()))
find.deleteAll()

let find = ec.entity.find('moqui.xmpp.XmppPushRegistration').condition('userId', ec.user.userId).condition('pushJid', pushJid).disableAuthz()
if (node) find = find.condition('node', node)
find.deleteAll()

targetList = Array.from(ec.entity.find('moqui.xmpp.XmppPushRegistration').condition('userId', userId).disableAuthz().list())
        .map((row) => { let options = {}; try { options = JSON.parse(row.optionsJson || '{}') } catch (err) { options = {} }
            return {pushRegistrationId: row.pushRegistrationId, pushJid: row.pushJid, node: row.node, options: options} })

const most = Number(System.getProperty('xmpp_upload_max_bytes') || 20971520)
if (!(Number(fileSize) > 0) || Number(fileSize) > most) { ec.message.addError('The file is too large'); return }
// at most so many slots of a user's in an hour, and so many bytes asked for in them
const hourAgo = new Date(Number(ec.user.nowTimestamp) - 3600000)
const recent = Array.from(ec.entity.find('moqui.xmpp.XmppUpload').condition('userId', ec.user.userId)
        .condition('createdDate', '>=', hourAgo).selectField('fileSize').disableAuthz().list())
const askedBytes = recent.reduce((sum, row) => sum + Number(row.fileSize || 0), 0)
if (recent.length >= 60 || askedBytes + Number(fileSize) > most * 10) { ec.message.addError('Too many uploads; try again later'); return }
let name = String(fileName || '').split(/[\\/]/).pop().replace(/[\u0000-\u001f]/g, '').trim()
if (!name || name === '.' || name === '..') name = 'file'
urlName = name.replace(/[^A-Za-z0-9._-]/g, '_').slice(-100)
token = ec.user.randomString(32)
const row = ec.entity.makeValue('moqui.xmpp.XmppUpload')
row.setSequencedIdPrimary()
const root = (System.getProperty('xmpp_upload_root') || 'dbresource://xmpp-upload').replace(/\/+$/, '')
row.setFields({tokenHash: ec.user.singleUseCodeHash(token), userId: ec.user.userId, fileName: name.slice(-200),
    contentType: contentType || 'application/octet-stream', fileSize: Number(fileSize),
    location: `${root}/${row.xmppUploadId}/${urlName}`, createdDate: ec.user.nowTimestamp}, true, null, null)
row.create()

const match = /\/xmpp-upload\/([A-Za-z0-9_-]+)\//.exec(String(url))
if (!match) { ec.message.addError('Not an upload of this server'); return }
const upload = ec.entity.find('moqui.xmpp.XmppUpload').condition('tokenHash', ec.user.singleUseCodeHash(match[1])).disableAuthz().one()
if (!upload || upload.userId !== ec.user.userId || !upload.completedDate) { ec.message.addError('No such upload of yours'); return }
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.canPost) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
const row = ec.entity.makeValue('moqui.chat.ChatAttachment')
row.setSequencedIdPrimary()
chatAttachmentId = row.chatAttachmentId
row.setFields({chatRoomId: chatRoomId, location: upload.location, fileName: upload.fileName, contentType: upload.contentType,
    fileSize: upload.fileSize, uploadedByUserId: ec.user.userId, uploadedDate: ec.user.nowTimestamp}, true, null, null)
row.create()

urlList = []
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.canRead) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
const base = String(System.getProperty('xmpp_upload_url') || '').replace(/\/+$/, '')
const secret = String(System.getProperty('xmpp_upload_secret') || '')
if (!base || !secret) return
const files = Array.from(ec.entity.find('moqui.chat.ChatAttachment').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq)
        .orderBy('chatAttachmentId').disableAuthz().list())
for (const file of files) {
    const token = String(ec.user.singleUseCodeHash(secret + ':' + file.chatAttachmentId)).replace(/[^A-Za-z0-9]/g, '').slice(0, 40)
    const tokenHash = ec.user.singleUseCodeHash(token)
    if (!ec.entity.find('moqui.xmpp.XmppUpload').condition('tokenHash', tokenHash).disableAuthz().count()) {
        const row = ec.entity.makeValue('moqui.xmpp.XmppUpload')
        row.setSequencedIdPrimary()
        row.setFields({tokenHash: tokenHash, fileName: file.fileName, contentType: file.contentType, fileSize: file.fileSize,
            location: file.location, chatAttachmentId: file.chatAttachmentId, createdDate: ec.user.nowTimestamp,
            completedDate: ec.user.nowTimestamp}, true, null, null)
        row.create()
    }
    const urlName = String(file.fileName || 'file').replace(/[^A-Za-z0-9._-]/g, '_').slice(-100)
    urlList.push(`${base}/xmpp-upload/${token}/${urlName}`)
}

const hourAgo = new Date(Number(ec.user.nowTimestamp) - 3600000)
for (const row of ec.entity.find('moqui.xmpp.XmppUpload').condition('completedDate', null).condition('createdDate', '<', hourAgo).disableAuthz().list()) {
    try {
        const ref = ec.resource.getLocationReference(row.location)
        if (ref && ref.exists) ref.delete()
        row.delete()
    } catch (err) { ec.logger.warn(`XMPP upload ${row.xmppUploadId} not removed: ${err}`) }
}
ec.entity.find('moqui.xmpp.XmppFastToken').condition('expireDate', '<', ec.user.nowTimestamp).disableAuthz().deleteAll()

const prop = (name) => String(System.getProperty(name) || '').trim()
const domain = prop('xmpp_domain').toLowerCase()
enabled = !!domain
server = domain || null
port = enabled && prop('xmpp_port') ? prop('xmpp_port') : null
tlsPort = enabled && prop('xmpp_tls_port') ? prop('xmpp_tls_port') : null
const base = prop('xmpp_upload_url') || (domain ? 'https://' + domain : '')
websocketUrl = enabled && prop('xmpp_websocket_enabled') === 'true' && base ? base.replace(/^http/, 'ws') + '/xmpp-websocket' : null
// XEP-0106: the characters a localpart cannot hold, escaped
const escapes = {' ': '\\20', '"': '\\22', '&': '\\26', "'": '\\27', '/': '\\2f', ':': '\\3a', '<': '\\3c', '>': '\\3e', '@': '\\40', '\\': '\\5c'}
const node = String(ec.user.username || '').toLowerCase().split('').map((ch) => escapes[ch] || ch).join('')
jid = enabled && node ? node + '@' + domain : null
appPasswordList = Array.from(ec.service.sync().name('org.moqui.impl.UserServices.get#UserAppPasswords').call()?.appPasswordList || [])
readyCount = appPasswordList.filter((row) => row.xmppReady === true).length

serviceList = []
reasonCode = null
if (String(System.getProperty('xmpp_turn_enabled') || '').trim() !== 'true') { reasonCode = 'turnOff'; return }
const userId = ec.user.userId
if (!userId) { reasonCode = 'notAllowed'; return }
// never for an external user (an app's client contacts), whatever the switch says
const external = ec.service.sync().name('org.moqui.impl.ChatServices.get#ExternalUsers').parameter('userIdList', [userId])
        .disableAuthz().call()?.anyExternal !== false
if (external) { reasonCode = 'notAllowed'; return }
// a credential is a relay for an hour or more: at most xmpp_turn_per_hour a user an hour (counted on the
// distributed cache moqui.xmpp.turn.issued by user and hour)
const perHour = Math.max(1, Number(System.getProperty('xmpp_turn_per_hour') || 30) || 30)
const issued = ec.cache.getCache('moqui.xmpp.turn.issued')
const hourKey = userId + ':' + Math.floor(Number(ec.user.nowTimestamp) / 3600000)
const count = Number(issued.get(hourKey) || 0)
if (count >= perHour) { reasonCode = 'rateLimited'; return }
issued.put(hourKey, count + 1)
const fresh = new Date(Number(ec.user.nowTimestamp) - 120000)
const node = Array.from(ec.entity.find('moqui.call.CallMediaNode').condition('heartbeatDate', '>', fresh).orderBy('-heartbeatDate')
        .limit(5).disableAuthz().list()).find((row) => row.draining !== 'Y' && row.turnUrls)
const made = ec.service.sync().name('org.moqui.impl.CallServices.make#IceServers')
        .parameters({callLegId: 'xmpp.' + ec.user.userId, turnUrls: node ? node.turnUrls : null}).disableAuthz().call()
for (const server of (made?.iceServers || [])) {
    const expires = Number(String(server.username || '').split(':')[0] || 0)
    for (const url of (server.urls || [])) {
        const match = /^(turns?):\[?([^\]?]+?)\]?(?::(\d+))?(?:\?transport=(udp|tcp))?$/.exec(String(url))
        if (!match) continue
        serviceList.push({type: match[1], host: match[2], port: match[3] || (match[1] === 'turns' ? '5349' : '3478'),
            transport: match[4] || (match[1] === 'turns' ? 'tcp' : 'udp'), username: server.username, password: server.credential,
            expires: expires ? new Date(expires * 1000).toISOString().replace(/\.\d{3}Z$/, 'Z') : ''})
    }
}
